// Which MTA GTFS-realtime feed actually carries a given route's live data.
// Mirrors bin/nyc-subway-status's and bin/nyc-subway-trip's FEED_PATHS
// groupings exactly — this needs to agree with them, since a mismatch here
// means fetching the wrong feed for a route.
//
// This has to be looked up per ROUTE, not trusted from a station record's
// single feedGroup field: many stop_ids serve routes from two different
// feeds at the same platform (e.g. 103 St's C/B stop_id — C lives in the
// ACE feed, B lives in BDFM, despite sharing a physical stop_id here). A
// pill's feedGroup has to reflect its own route, or the "other" route at
// that stop silently never gets fetched from the right feed.
var ROUTE_TO_FEED = {
  "1": "1234567S", "2": "1234567S", "3": "1234567S", "4": "1234567S",
  "5": "1234567S", "6": "1234567S", "7": "1234567S", "GS": "1234567S",
  "A": "ACE", "C": "ACE", "E": "ACE",
  "B": "BDFM", "D": "BDFM", "F": "BDFM", "M": "BDFM",
  "G": "G",
  "J": "JZ", "Z": "JZ",
  "N": "NQRW", "Q": "NQRW", "R": "NQRW", "W": "NQRW",
  "L": "L",
  "SIR": "SIR"
}

function feedGroupForRoute(route, fallback) {
  return ROUTE_TO_FEED[route] || fallback
}

// Physical service-group order, matching manifest.json's feedGroup enum
// exactly. Route lists throughout the UI ("browse by line", arrivals-list
// bullets, station-result pills) group by this instead of plain alphabetical
// sort, which otherwise scatters e.g. D and F away from B despite all three
// being the same physical BDFM group.
var ROUTE_GROUP_ORDER = ["1234567S", "ACE", "BDFM", "G", "JZ", "NQRW", "L", "SIR"]

// Within-group order: the group's own natural line order. "S" (a bare
// shuttle code, confirmed the only shuttle spelling in the actual station
// data — no "GS") is listed in each of the three groups it can belong to
// (42 St Shuttle, Franklin Av Shuttle, Rockaway Park Shuttle), since which
// one a given "S" means depends entirely on the feedGroupHint passed in.
var ROUTE_ORDER_WITHIN_GROUP = {
  "1234567S": ["1", "2", "3", "4", "5", "6", "7", "S"],
  "ACE": ["A", "C", "E", "S"],
  "BDFM": ["B", "D", "F", "M", "S"],
  "G": ["G"],
  "JZ": ["J", "Z"],
  "NQRW": ["N", "Q", "R", "W"],
  "L": ["L"],
  "SIR": ["SIR"]
}

// Sort key for one route. feedGroupHint disambiguates the one route code
// that isn't globally one-to-one with a service group — "S" is reused by
// three unrelated shuttles (42 St, Franklin Av, Rockaway Park) living in
// three different feeds, which is exactly why ROUTE_TO_FEED has no "S" key
// of its own. Pass the specific pill's/station's own feedGroup when it's
// known; falls back to the 42 St Shuttle's group otherwise.
function routeSortKey(route, feedGroupHint) {
  var r = String(route || "").toUpperCase()
  var group = feedGroupHint || ROUTE_TO_FEED[r] || "1234567S"
  var groupIndex = ROUTE_GROUP_ORDER.indexOf(group)
  if (groupIndex === -1) groupIndex = ROUTE_GROUP_ORDER.length
  var within = ROUTE_ORDER_WITHIN_GROUP[group] || []
  var withinIndex = within.indexOf(r)
  if (withinIndex === -1) withinIndex = within.length
  return groupIndex * 100 + withinIndex
}

function makeRouteComparator(feedGroupHint) {
  return function(a, b) { return routeSortKey(a, feedGroupHint) - routeSortKey(b, feedGroupHint) }
}

// Distinct routes across every station, grouped by MTA physical service
// group (see ROUTE_GROUP_ORDER), for the "browse by line" picker.
function allRoutes() {
  var seen = {}
  var out = []
  for (var i = 0; i < STATIONS.length; i++) {
    var routes = STATIONS[i].routes
    for (var j = 0; j < routes.length; j++) {
      if (!seen[routes[j]]) { seen[routes[j]] = true; out.push(routes[j]) }
    }
  }
  out.sort(makeRouteComparator())
  return out
}

// Search by name substring (case-insensitive) and/or a single route filter.
// Blank query + no route returns nothing (avoid handing the UI all 496 rows
// before the user has narrowed anything down).
function searchStations(query, routeFilter, limit) {
  var q = String(query || "").trim().toLowerCase()
  var cap = Math.max(1, parseInt(limit, 10) || 40)
  if (q === "" && !routeFilter) return []

  var out = []
  for (var i = 0; i < STATIONS.length && out.length < cap; i++) {
    var s = STATIONS[i]
    if (routeFilter && s.routes.indexOf(routeFilter) === -1) continue
    if (q !== "" && s.name.toLowerCase().indexOf(q) === -1) continue
    out.push(s)
  }
  return out
}

// Station names the MTA's own data splits into multiple complex IDs despite
// being the same real-world station to any rider — as opposed to the ~55
// other same-name groups in this dataset, which are genuinely different,
// unconnected stations that happen to share a plain cross-street name (the
// four separate "23 St" stations on four different avenues, "96 St"/
// "125 St"/"86 St" likewise). Checked every one of those groups for a
// distinguishing signal: distance doesn't work (23 St's stations are as
// close together as Penn Station's two halves), and neither does the GTFS
// static transfers.txt (it doesn't link Penn Station's two complexes at
// all — that connection is an out-of-system passageway, exit fare control
// and tap in again, not the same fare-controlled area, unlike a true
// unified complex like Times Sq or Fulton St). So this is a small hand-
// curated, name-keyed exception list rather than an automatic rule; extend
// it by hand if another genuine case turns up, don't try to derive one.
//
//   34 St-Penn Station — 1/2/3 (complex 318) and A/C/E (complex 164) fail
//   every technical "same complex" test above, but every rider calls this
//   one station.
var SAME_STATION_OVERRIDES = {
  "34 St-Penn Station": true
}

// A station's true identity is its MTA Complex ID, not its name, with the
// one hand-curated exception above. Name (even name+borough) isn't
// reliable on its own: "103 St" alone is three unrelated physical stations
// in Manhattan on three different lines, roughly half a mile apart —
// sharing a name but not a platform, tunnel, or fare control. Complex ID
// is the field the MTA itself uses to say "these stop_ids are the same
// physical complex" (confirmed: Times Sq-42 St's four stop_ids — 1/2/3, 7,
// S, N/Q/R/W — all carry complex 611; 103 St's three stop_ids carry three
// different complex IDs). This matters beyond cosmetics: it's the exact
// mechanism transfer routing uses to decide where a transfer is actually
// walkable.
function complexKey(station) {
  if (SAME_STATION_OVERRIDES[station.name]) return "name:" + station.name
  return station.complexId
}

// Same search as above, but collapsed to one row per station complex: a
// complex like "14 St-Union Sq" has a separate GTFS stop_id per line
// grouping (4/5/6, L, N/Q/R/W), each with its own feed and direction
// labels — this merges those into one row with every route's pill on it,
// so picking a specific pill is what actually chooses which stop_id.
function searchStationGroups(query, routeFilter, limit) {
  var flat = searchStations(query, routeFilter, STATIONS.length)
  var order = []
  var byKey = {}
  for (var i = 0; i < flat.length; i++) {
    var s = flat[i]
    var key = complexKey(s)
    if (!byKey[key]) {
      byKey[key] = { name: s.name, borough: s.borough, key: key, pills: [] }
      order.push(key)
    }
    var pills = byKey[key].pills
    for (var j = 0; j < s.routes.length; j++) {
      pills.push({ route: s.routes[j], stopId: s.id, feedGroup: feedGroupForRoute(s.routes[j], s.feedGroup), north: s.north, south: s.south })
    }
  }

  var cap = Math.max(1, parseInt(limit, 10) || 25)
  var out = []
  for (var k = 0; k < order.length && out.length < cap; k++) {
    var group = byKey[order[k]]
    group.pills.sort(function(a, b) { return routeSortKey(a.route, a.feedGroup) - routeSortKey(b.route, b.feedGroup) })
    out.push(group)
  }
  return out
}

function stationById(id) {
  for (var i = 0; i < STATIONS.length; i++) if (STATIONS[i].id === id) return STATIONS[i]
  return null
}

// The widget's stopId setting is usually one GTFS stop_id, but a whole-
// complex pick (see dominantFeedGroupStopIds) sets it to a comma-joined
// list of every platform sharing one feed, e.g. "631,723,901" for Grand
// Central's 4/5/6, 7, and S. These three helpers are how the rest of the
// plugin reads that either shape without caring which one it got.

// Every stop_id in a (possibly comma-joined) stopId setting.
function stopIdList(stopId) {
  var out = []
  var parts = String(stopId || "").split(",")
  for (var i = 0; i < parts.length; i++) {
    var s = parts[i].trim()
    if (s !== "") out.push(s)
  }
  return out
}

// The first stop_id — unchanged when there's no comma. Lookups that are
// inherently about ONE physical platform (direction tab labels, the
// arrivals-list context strip's neighbor stations) key off this, the same
// stop_id a single-pill pick would have used before whole-complex picks
// existed.
function primaryStopId(stopId) {
  var ids = stopIdList(stopId)
  return ids.length > 0 ? ids[0] : String(stopId || "")
}

// Union of routes served across every stop_id in a (possibly multi-id)
// stopId setting, in physical service-group order — feeds the "all routes
// serving this stop" badge row so a whole-complex pick shows every merged
// line, not just the primary platform's.
function routesForStopId(stopId) {
  var ids = stopIdList(stopId)
  var seen = {}
  var out = []
  for (var i = 0; i < ids.length; i++) {
    var station = stationById(ids[i])
    if (!station) continue
    for (var j = 0; j < station.routes.length; j++) {
      var r = station.routes[j]
      if (!seen[r]) { seen[r] = true; out.push(r) }
    }
  }
  out.sort(makeRouteComparator())
  return out
}

// True when a station-row's pills cover more than one MTA realtime feed
// (e.g. Penn Station's 1/2/3 on "1234567S" plus A/C/E on "ACE"; Times
// Sq-42 St and Union Sq are the same way). A whole-row click can only ever
// track ONE feed per poll (see dominantFeedGroupStopIds below), so silently
// picking "the dominant feed" here would look like tracking the whole
// station while actually dropping every line on the other feed with no
// indication — exactly the confusing crossover this flags so the caller
// can require a specific pill tap instead.
function pillsSpanMultipleFeeds(pills) {
  var seen = {}
  var count = 0
  for (var i = 0; i < pills.length; i++) {
    if (!seen[pills[i].feedGroup]) { seen[pills[i].feedGroup] = true; count++ }
  }
  return count > 1
}

// Given one station-search-result row's pills (searchStationGroups), finds
// whichever feedGroup has the most pills at that row and returns its
// deduped stop_ids in pill order — what a whole-row click (pick the whole
// complex, not one line) actually tracks. Complexes spanning a single feed
// (Grand Central: all of 4/5/6/7/S on "1234567S") get every line; a
// complex split across feeds (e.g. Times Sq-42 St, also NQRW) only gets
// whichever feed has the most lines there — merging across feeds would
// mean polling more than one feed per refresh, out of scope for this. Only
// meaningful when !pillsSpanMultipleFeeds would be false; callers should
// check that first and require a specific pill tap otherwise (see Panel.qml).
function dominantFeedGroupStopIds(pills) {
  var counts = {}
  var order = []
  for (var i = 0; i < pills.length; i++) {
    var fg = pills[i].feedGroup
    if (!(fg in counts)) { counts[fg] = 0; order.push(fg) }
    counts[fg]++
  }
  var best = order[0]
  for (var k = 1; k < order.length; k++) {
    if (counts[order[k]] > counts[best]) best = order[k]
  }
  var seenIds = {}
  var stopIds = []
  for (var j = 0; j < pills.length; j++) {
    if (pills[j].feedGroup !== best) continue
    if (seenIds[pills[j].stopId]) continue
    seenIds[pills[j].stopId] = true
    stopIds.push(pills[j].stopId)
  }
  return { feedGroup: best, stopIds: stopIds }
}

// Builds the same {name, borough, key, pills} shape searchStationGroups
// produces, but for a specific (possibly comma-joined, whole-complex)
// stopId setting rather than a name/route search — used to default the
// trip planner's origin to whatever station the widget is currently
// tracking. Returns null if none of the ids resolve (e.g. a hand-typed
// stop_id outside the bundled dataset).
function stationGroupForStopId(stopId) {
  var ids = stopIdList(stopId)
  var primary = null
  var pills = []
  for (var i = 0; i < ids.length; i++) {
    var s = stationById(ids[i])
    if (!s) continue
    if (!primary) primary = s
    for (var j = 0; j < s.routes.length; j++) {
      pills.push({ route: s.routes[j], stopId: s.id, feedGroup: feedGroupForRoute(s.routes[j], s.feedGroup), north: s.north, south: s.south })
    }
  }
  if (!primary) return null
  pills.sort(function(a, b) { return routeSortKey(a.route, a.feedGroup) - routeSortKey(b.route, b.feedGroup) })
  return { name: primary.name, borough: primary.borough, key: complexKey(primary), pills: pills }
}

// Complexes that could serve as a one-transfer bridge between an origin
// and a destination: any complex (other than the origin/destination
// themselves) whose combined routes include at least one origin route
// AND at least one destination route. Each candidate carries the specific
// stop_id/feedGroup pill for each side, since a multi-line complex has a
// different stop_id per line grouping. Purely static — no live data
// needed to find candidates, only to confirm a live trip actually
// connects each leg.
function transferCandidates(originRoutes, destRoutes, excludeKeys) {
  var originSet = {}
  for (var i = 0; i < originRoutes.length; i++) originSet[originRoutes[i]] = true
  var destSet = {}
  for (var j = 0; j < destRoutes.length; j++) destSet[destRoutes[j]] = true
  var excluded = {}
  for (var k = 0; k < (excludeKeys || []).length; k++) excluded[excludeKeys[k]] = true

  var byKey = {}
  var order = []
  for (var m = 0; m < STATIONS.length; m++) {
    var s = STATIONS[m]
    var key = complexKey(s)
    if (excluded[key]) continue
    if (!byKey[key]) { byKey[key] = { name: s.name, borough: s.borough, key: key, pills: [] }; order.push(key) }
    for (var r = 0; r < s.routes.length; r++) {
      byKey[key].pills.push({ route: s.routes[r], stopId: s.id, feedGroup: feedGroupForRoute(s.routes[r], s.feedGroup) })
    }
  }

  var out = []
  for (var n = 0; n < order.length; n++) {
    var complex = byKey[order[n]]
    var fromOrigin = null
    var toDest = null
    for (var p = 0; p < complex.pills.length; p++) {
      var pill = complex.pills[p]
      if (!fromOrigin && originSet[pill.route]) fromOrigin = pill
      if (!toDest && destSet[pill.route]) toDest = pill
    }
    if (fromOrigin && toDest && fromOrigin.route !== toDest.route) {
      out.push({ name: complex.name, borough: complex.borough, key: complex.key, entryPill: fromOrigin, exitPill: toDest })
    }
  }
  return out
}

if (typeof module !== "undefined") {
  module.exports = {
    STATIONS: STATIONS,
    allRoutes: allRoutes,
    searchStations: searchStations,
    searchStationGroups: searchStationGroups,
    stationById: stationById,
    transferCandidates: transferCandidates,
    feedGroupForRoute: feedGroupForRoute,
    routeSortKey: routeSortKey,
    makeRouteComparator: makeRouteComparator,
    stopIdList: stopIdList,
    primaryStopId: primaryStopId,
    routesForStopId: routesForStopId,
    pillsSpanMultipleFeeds: pillsSpanMultipleFeeds,
    dominantFeedGroupStopIds: dominantFeedGroupStopIds,
    stationGroupForStopId: stationGroupForStopId
  }
}
